-export const tokenHandler = (config: InternalAxiosRequestConfig) => {
-  const token = localStorage.getItem(TOKEN_STORAGE_KEY) ?? getTokenFromCookies();
-
-  if (token !== undefined) {
-    config.headers.Authorization = `Bearer ${token}`;
-  }
-
-  return config;
-};
